//! The schemas of `mcp`'s tools, lowered from the CLI's OpenAPI-flavored JSON Schema to the
//! subset MCP clients take: `nullable` as `null` in `type`, `oneOf` as `anyOf` (discriminated
//! variants carry their tag as a `const`), no `discriminator` or `x-` keys, formats outside JSON
//! Schema's as descriptions. Clients that do not resolve `$ref` get every reference inlined.
use serde_json::{json, Map, Value};

use super::schema::hint;

/// What a client takes of JSON Schema.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Dialect {
    /// `$ref` and `$defs`: Claude, VS Code.
    Refs,
    /// No references: every schema inlined, cycles cut. Cursor, OpenAI, Gemini, and unknown
    /// clients.
    Inline,
}

impl Dialect {
    pub const NAMES: [&'static str; 6] =
        ["claude", "vscode", "cursor", "openai", "gemini", "other"];

    /// The dialect of a client, by the name it gives in `clientInfo` or on the command line.
    pub fn of(client: &str) -> Self {
        let client = client.to_lowercase();
        let refs = ["claude", "vscode", "visual studio code", "copilot"];
        match refs.iter().any(|name| client.contains(name)) && !client.contains("cursor") {
            true => Self::Refs,
            false => Self::Inline,
        }
    }
}

/// How deep inlined references go before a cycle is cut.
const MAX_INLINE: usize = 8;

/// Output schemas stop describing fields below this depth: they document, they do not check.
const OUTPUT_DEPTH: usize = 2;

/// The formats JSON Schema defines, which clients may check; others become descriptions.
const FORMATS: [&str; 10] = [
    "date-time",
    "date",
    "time",
    "duration",
    "email",
    "hostname",
    "ipv4",
    "ipv6",
    "uri",
    "uuid",
];

/// A tool's `inputSchema` for `dialect`, or with `output` its `outputSchema`, always inlined.
pub fn lower(schema: &Value, dialect: Dialect, output: bool) -> Value {
    let dialect = if output { Dialect::Inline } else { dialect };
    let defs = schema.get("$defs").cloned().unwrap_or_else(|| json!({}));
    let mut lowering = Lowering {
        defs: &defs,
        dialect,
        output,
        stack: Vec::new(),
    };
    let mut lowered = lowering.schema(schema, 0);
    if let Some(map) = lowered.as_object_mut() {
        map.remove("$defs");
        if dialect == Dialect::Refs && defs.as_object().is_some_and(|defs| !defs.is_empty()) {
            let defs: Map<String, Value> = defs
                .as_object()
                .into_iter()
                .flatten()
                .map(|(name, def)| (name.clone(), lowering.schema(def, 1)))
                .collect();
            map.insert("$defs".into(), Value::Object(defs));
        }
    }
    lowered
}

struct Lowering<'d> {
    defs: &'d Value,
    dialect: Dialect,
    output: bool,
    stack: Vec<String>,
}

impl Lowering<'_> {
    fn schema(&mut self, schema: &Value, depth: usize) -> Value {
        let Value::Object(map) = schema else {
            return schema.clone();
        };
        if self.output && depth > OUTPUT_DEPTH {
            return json!({});
        }
        if let Some(reference) = map.get("$ref").and_then(Value::as_str) {
            return self.reference(map, reference, depth);
        }
        let mut out = Map::new();
        let nullable = map.get("nullable") == Some(&Value::Bool(true)) || self.loose(depth);
        for (key, value) in map {
            match key.as_str() {
                "nullable" | "discriminator" | "xml" | "externalDocs" | "readOnly"
                | "writeOnly" | "$defs" => {}
                key if key.starts_with("x-") => {}
                "example" => {
                    out.insert("examples".into(), json!([value]));
                }
                "format" => self.format(value, map, &mut out),
                "properties" => {
                    let mut properties = Map::new();
                    for (name, property) in value.as_object().into_iter().flatten() {
                        if !self.hidden(property) {
                            properties.insert(name.clone(), self.schema(property, depth + 1));
                        }
                    }
                    out.insert(key.clone(), Value::Object(properties));
                }
                "required" | "additionalProperties" if self.output => {}
                "required" => {
                    let hidden = |name: &Value| {
                        name.as_str()
                            .and_then(|name| map.get("properties")?.get(name))
                            .is_some_and(|property| self.hidden(property))
                    };
                    let required: Vec<Value> = value
                        .as_array()
                        .into_iter()
                        .flatten()
                        .filter(|name| !hidden(name))
                        .cloned()
                        .collect();
                    out.insert(key.clone(), Value::Array(required));
                }
                "enum" | "pattern" | "minimum" | "maximum" | "exclusiveMinimum"
                | "exclusiveMaximum" | "minLength" | "maxLength" | "minItems" | "maxItems"
                | "multipleOf" | "uniqueItems"
                    if self.output => {}
                "oneOf" | "anyOf" | "allOf" => {
                    let variants: Vec<Value> = value
                        .as_array()
                        .into_iter()
                        .flatten()
                        .map(|variant| self.schema(variant, depth + 1))
                        .collect();
                    let key = if key == "allOf" { "allOf" } else { "anyOf" };
                    out.insert(key.into(), Value::Array(variants));
                }
                "items" | "additionalProperties" | "not" => {
                    out.insert(key.clone(), self.schema(value, depth + 1));
                }
                _ => {
                    out.insert(key.clone(), value.clone());
                }
            }
        }
        if nullable {
            null_too(&mut out);
        }
        Value::Object(out)
    }

    /// Output schemas describe what the SDK decoded: optional fields may be null at any depth
    /// below the root, and nothing is required, closed or bounded.
    fn loose(&self, depth: usize) -> bool {
        self.output && depth > 0
    }

    /// Fields the other direction owns: `readOnly` in a request, `writeOnly` in a response.
    fn hidden(&self, property: &Value) -> bool {
        let key = if self.output { "writeOnly" } else { "readOnly" };
        property[key] == true
    }

    fn format(&self, format: &Value, map: &Map<String, Value>, out: &mut Map<String, Value>) {
        let Some(name) = format.as_str() else {
            return;
        };
        if FORMATS.contains(&name) {
            out.insert("format".into(), format.clone());
            return;
        }
        if [
            "int32", "int64", "float", "double", "binary", "byte", "password",
        ]
        .contains(&name)
            || map.contains_key("description")
        {
            return;
        }
        let about = match hint(name) {
            Some(hint) => capitalize(hint),
            None => format!("A {name}"),
        };
        out.insert("description".into(), about.into());
    }

    fn reference(&mut self, map: &Map<String, Value>, reference: &str, depth: usize) -> Value {
        let name = reference.trim_start_matches("#/$defs/").to_owned();
        let siblings: Map<String, Value> = map
            .iter()
            .filter(|(key, _)| *key != "$ref")
            .map(|(key, value)| (key.clone(), value.clone()))
            .collect();
        let nullable = siblings.get("nullable") == Some(&Value::Bool(true)) || self.loose(depth);
        let mut target = match self.dialect {
            Dialect::Refs => json!({"$ref": reference}),
            Dialect::Inline => match self.defs.get(&name) {
                Some(def) if !self.stack.contains(&name) && self.stack.len() < MAX_INLINE => {
                    self.stack.push(name);
                    let inlined = self.schema(def, depth);
                    self.stack.pop();
                    inlined
                }
                _ => json!({"type": "object", "description": format!("A {name}, as above")}),
            },
        };
        let siblings = self.schema(&Value::Object(siblings), depth);
        let Value::Object(siblings) = siblings else {
            return target;
        };
        if nullable {
            let mut wrapped = Map::new();
            wrapped.insert("anyOf".into(), json!([target, {"type": "null"}]));
            target = Value::Object(wrapped);
        }
        if let Value::Object(target) = &mut target {
            for (key, value) in siblings {
                if !(key == "type" && value.is_array()) && !(key == "enum") {
                    target.insert(key, value);
                }
            }
        }
        target
    }
}

/// Lets a schema take `null` as well.
fn null_too(out: &mut Map<String, Value>) {
    if let Some(values) = out.get_mut("enum").and_then(Value::as_array_mut) {
        if !values.contains(&Value::Null) {
            values.push(Value::Null);
        }
    }
    match out.get("type").cloned() {
        Some(Value::String(kind)) => {
            out.insert("type".into(), json!([kind, "null"]));
        }
        Some(Value::Array(mut kinds)) => {
            if !kinds.contains(&json!("null")) {
                kinds.push(json!("null"));
            }
            out.insert("type".into(), Value::Array(kinds));
        }
        _ => {
            if let Some(Value::Array(variants)) = out.get_mut("anyOf") {
                if !variants.contains(&json!({"type": "null"})) {
                    variants.push(json!({"type": "null"}));
                }
            }
        }
    }
}

fn capitalize(text: &str) -> String {
    let mut chars = text.chars();
    chars
        .next()
        .map(|first| first.to_uppercase().chain(chars).collect())
        .unwrap_or_default()
}

#[cfg(test)]
mod tests {
    use super::*;

    fn body() -> Value {
        json!({
            "type": "object",
            "required": ["name", "id"],
            "additionalProperties": false,
            "properties": {
                "id": {"type": "string", "readOnly": true},
                "name": {"type": "string", "nullable": true, "x-order": 1},
                "amount": {"type": "string", "format": "decimal"},
                "count": {"type": "integer", "format": "int32", "minimum": 0},
                "at": {"type": "string", "format": "date-time", "example": "2026-01-01T00:00:00Z"},
                "owner": {"type": "string", "format": "MeteroidId"},
                "status": {"type": "string", "enum": ["A", "B"], "nullable": true},
                "parent": {"$ref": "#/$defs/Node", "nullable": true},
                "kind": {"oneOf": [{"type": "object", "properties": {"type": {"const": "x"}}}],
                         "discriminator": {"propertyName": "type"}},
            },
            "$defs": {"Node": {"type": "object", "properties": {"child": {"$ref": "#/$defs/Node"}}}},
        })
    }

    #[test]
    fn openapi_keywords_become_json_schema() {
        let lowered = lower(&body(), Dialect::Refs, false);
        let properties = &lowered["properties"];
        assert!(properties.get("id").is_none());
        assert_eq!(lowered["required"], json!(["name"]));
        assert_eq!(properties["name"], json!({"type": ["string", "null"]}));
        assert_eq!(
            properties["amount"],
            json!({"type": "string", "description": "A decimal number, as a string"})
        );
        assert_eq!(
            properties["count"],
            json!({"type": "integer", "minimum": 0})
        );
        assert_eq!(
            properties["at"]["examples"],
            json!(["2026-01-01T00:00:00Z"])
        );
        assert_eq!(properties["at"]["format"], "date-time");
        assert_eq!(properties["owner"]["description"], "A MeteroidId");
        assert_eq!(properties["status"]["enum"], json!(["A", "B", null]));
        assert_eq!(
            properties["parent"],
            json!({"anyOf": [{"$ref": "#/$defs/Node"}, {"type": "null"}]})
        );
        assert!(properties["kind"].get("discriminator").is_none());
        assert!(properties["kind"]["anyOf"].is_array());
        assert!(lowered["$defs"]["Node"].is_object());
    }

    #[test]
    fn inline_clients_get_no_references_and_cycles_are_cut() {
        let lowered = lower(&body(), Dialect::Inline, false);
        assert!(lowered.get("$defs").is_none());
        let text = lowered.to_string();
        assert!(!text.contains("$ref"), "{text}");
        let parent = &lowered["properties"]["parent"]["anyOf"][0];
        assert_eq!(
            parent["properties"]["child"],
            json!({"type": "object", "description": "A Node, as above"})
        );
    }

    #[test]
    fn outputs_are_loose() {
        let lowered = lower(&body(), Dialect::Inline, true);
        assert!(lowered.get("required").is_none());
        assert!(lowered.get("additionalProperties").is_none());
        assert_eq!(lowered["type"], "object");
        assert_eq!(
            lowered["properties"]["count"],
            json!({"type": ["integer", "null"]})
        );
        assert_eq!(
            lowered["properties"]["id"]["type"],
            json!(["string", "null"])
        );
        assert!(lowered["properties"]["status"].get("enum").is_none());
    }

    #[test]
    fn clients_by_name() {
        assert_eq!(Dialect::of("claude-code"), Dialect::Refs);
        assert_eq!(Dialect::of("Visual Studio Code"), Dialect::Refs);
        assert_eq!(Dialect::of("cursor-vscode"), Dialect::Inline);
        assert_eq!(Dialect::of("openai-mcp"), Dialect::Inline);
        assert_eq!(Dialect::of("whatever"), Dialect::Inline);
    }
}
